package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * The sheet's figures as the screen shows them: each person's claimed and due-total, and the sheet's
 * claimed-total and due-total. A change takes a snapshot before it and, once its own audit lines are
 * written, records a ROLLUP line per person whose figures moved and a TOTALS line when the totals did.
 */
@Service
public class RollupService {

    /** A person's figures, as text with two decimals; the due-total is "n/a" when they have none. */
    public record Figures(String name, String claimed, String dueTotal) {}

    /** Each person's figures by id, in the order they were added, and the sheet's totals. */
    public record Rollup(Map<Long, Figures> people, String claimedTotal, String dueTotal) {}

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final RateRepository rates;
    private final SheetRepository sheets;
    private final Audit audit;

    public RollupService(PersonRepository people, ClaimRepository claims, RateRepository rates,
            SheetRepository sheets, Audit audit) {
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.sheets = sheets;
        this.audit = audit;
    }

    /**
     * The sheet's figures now. Only open and settled claims count (a held person's open ones do not); a person's due-total is the sum of
     * their figures (those with one), n/a when their grade has no rate in force on the sheet's today
     * and no counting claim of theirs keeps a fixed (settled or stated) figure.
     */
    @Transactional(readOnly = true)
    public Rollup snapshot(String sheetId) {
        LocalDate today = sheets.findById(sheetId).map(Sheet::getToday).orElseGet(LocalDate::now);
        Map<Long, List<Claim>> byPerson = claims.findBySheetIdOrderByIdDesc(sheetId).stream()
                .filter(c -> c.getStatus().counts())
                .collect(Collectors.groupingBy(Claim::getPersonId));
        Map<Long, Figures> out = new LinkedHashMap<>();
        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
        BigDecimal dueTotal = BigDecimal.ZERO.setScale(2);
        for (Person p : people.findBySheetIdOrderByIdAsc(sheetId)) {
            List<Claim> counted = byPerson.getOrDefault(p.getId(), List.of()).stream()
                    .filter(c -> counts(p, c))
                    .toList();
            BigDecimal claimed = BigDecimal.ZERO.setScale(2);
            BigDecimal due = BigDecimal.ZERO.setScale(2);
            for (Claim c : counted) {
                claimed = claimed.add(c.getAmount());
                BigDecimal figure = figure(sheetId, p, c);
                if (figure != null) due = due.add(figure);
            }
            boolean rated = rates.findInForce(sheetId, p.getGrade(), today).isPresent();
            boolean anyFixed = counted.stream().anyMatch(Claim::keepsFigure);
            claimedTotal = claimedTotal.add(claimed);
            if (rated || anyFixed) dueTotal = dueTotal.add(due);
            out.put(p.getId(), new Figures(p.getName(), text(claimed), rated || anyFixed ? text(due) : "n/a"));
        }
        return new Rollup(out, text(claimedTotal), text(dueTotal));
    }

    /**
     * Whether a claim counts in the live totals: open and settled claims do, except the open claims
     * of a person on hold.
     */
    public static boolean counts(Person person, Claim claim) {
        return claim.getStatus().counts() && !(person.isHeld() && claim.getStatus() == ClaimStatus.OPEN);
    }

    /**
     * Record, once the change commits, a ROLLUP line for each person whose figures moved since
     * {@code before} (a person who did not exist then counts as moved), then a TOTALS line when the
     * sheet's totals moved.
     */
    @Transactional(readOnly = true)
    public void recordChanges(String sheetId, String user, Rollup before) {
        Rollup after = snapshot(sheetId);
        List<String> lines = new ArrayList<>();
        after.people().forEach((id, now) -> {
            Figures was = before.people().get(id);
            if (was == null || !was.claimed().equals(now.claimed()) || !was.dueTotal().equals(now.dueTotal())) {
                lines.add("ROLLUP sheet=" + sheetId + " by=" + user + " person=" + now.name()
                        + " claimed=" + now.claimed() + " due-total=" + now.dueTotal());
            }
        });
        if (!Objects.equals(before.claimedTotal(), after.claimedTotal())
                || !Objects.equals(before.dueTotal(), after.dueTotal())) {
            lines.add("TOTALS sheet=" + sheetId + " by=" + user + " claimed-total=" + after.claimedTotal()
                    + " due-total=" + after.dueTotal());
        }
        lines.forEach(audit::recordOnCommit);
    }

    /**
     * The figure a claim shows: a settled claim's fixed due, else the figure its person's last
     * statement bound it to, else its amount times the rate in force on its date, raised to the
     * sheet's floor; null when none.
     */
    @Transactional(readOnly = true)
    public BigDecimal figure(String sheetId, Person person, Claim claim) {
        if (claim.getDue() != null) return claim.getDue();
        if (claim.isStated()) return claim.getStatedDue();
        BigDecimal floor = sheets.findById(sheetId).map(Sheet::getFloor).orElse(BigDecimal.ZERO);
        return rates.findInForce(sheetId, person.getGrade(), claim.getDate())
                .map(rate -> due(claim.getAmount(), rate).max(floor).setScale(2))
                .orElse(null);
    }

    /** The amount times the rate's percent, rounded half to even to cents (as the screen works it out). */
    private static BigDecimal due(BigDecimal amount, Rate rate) {
        return amount.multiply(rate.getPct()).movePointLeft(2).setScale(2, RoundingMode.HALF_EVEN);
    }

    private static String text(BigDecimal amount) {
        return amount.setScale(2).toPlainString();
    }
}
package net.officefloor.hq.app.settings;

import java.math.BigDecimal;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** The sheet's settings (its clerk limit and floor) and the roles it gives user names. */
@Service
public class SettingsService {

    private final SheetRoleRepository roles;
    private final SheetService sheets;
    private final RollupService rollups;
    private final Audit audit;

    public SettingsService(SheetRoleRepository roles, SheetService sheets, RollupService rollups, Audit audit) {
        this.roles = roles;
        this.sheets = sheets;
        this.rollups = rollups;
        this.audit = audit;
    }

    /** The sheet's settings now. */
    @Transactional
    public Sheet settings(String sheetId, String user) {
        return sheets.load(sheetId, user);
    }

    /**
     * Save the settings given: {@code setClerkLimit} the clerk limit (null: no limit), a non-null
     * {@code floor} the floor; each one saved is audited, even when its value is the same. A floor
     * that moves live dues records the rollups that moved.
     */
    @Transactional
    public Sheet save(String sheetId, String user, boolean setClerkLimit, BigDecimal clerkLimit, BigDecimal floor) {
        Sheet sheet = sheets.lock(sheetId, user);
        if (setClerkLimit) {
            sheet.setClerkLimit(clerkLimit);
            audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user
                    + " key=clerk-limit value=" + (clerkLimit == null ? "" : clerkLimit.toPlainString()));
        }
        if (floor != null) {
            RollupService.Rollup before = rollups.snapshot(sheetId);
            sheet.setFloor(floor);
            audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user
                    + " key=floor value=" + floor.toPlainString());
            rollups.recordChanges(sheetId, user, before);
        }
        return sheet;
    }

    /** The roles the sheet gives user names, by name; a name not among them is a clerk. */
    @Transactional(readOnly = true)
    public List<SheetRole> roles(String sheetId) {
        return roles.findBySheetIdOrderByUserNameAsc(sheetId);
    }

    /** The role the sheet gives a user name; clerk when it gives none. */
    @Transactional(readOnly = true)
    public Role roleOf(String sheetId, String userName) {
        return roles.findBySheetIdAndUserName(sheetId, userName).map(SheetRole::getRole).orElse(Role.CLERK);
    }

    /** Give a user name a role, replacing the one it had. */
    @Transactional
    public SheetRole setRole(String sheetId, String user, String userName, Role role) {
        sheets.lock(sheetId, user);
        SheetRole entry = roles.findBySheetIdAndUserName(sheetId, userName)
                .orElseGet(() -> new SheetRole(sheetId, userName, role));
        entry.setRole(role);
        SheetRole saved = roles.saveAndFlush(entry);
        audit.recordOnCommit("ROLE_SET sheet=" + sheetId + " by=" + user
                + " user=" + userName + " role=" + role.name().toLowerCase());
        return saved;
    }
}
package net.officefloor.hq.app.settings;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.util.List;
import net.officefloor.hq.app.session.SessionController;
import net.officefloor.hq.app.sheet.Sheet;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}")
public class SettingsController {

    /**
     * The sheet's settings, as text with two decimals: the clerk limit (null when there is none) and
     * the floor.
     */
    public record SettingsView(String clerkLimit, String floor) {
        static SettingsView of(Sheet sheet) {
            BigDecimal limit = sheet.getClerkLimit();
            return new SettingsView(limit == null ? null : limit.setScale(2).toPlainString(),
                    sheet.getFloor().setScale(2).toPlainString());
        }
    }

    /**
     * The settings to save; a setting left out (null) is not changed. The clerk limit is 0.00 or more
     * with up to two decimals, blank for no limit; the floor is 0.00 or more with up to two decimals.
     */
    public record SettingsForm(
            @Pattern(regexp = "\\s*|\\d{1,13}(\\.\\d{1,2})?") String clerkLimit,
            @Pattern(regexp = "\\d{1,13}(\\.\\d{1,2})?") String floor) {

        BigDecimal clerkLimitValue() {
            return clerkLimit == null || clerkLimit.isBlank() ? null : new BigDecimal(clerkLimit).setScale(2);
        }

        BigDecimal floorValue() {
            return floor == null ? null : new BigDecimal(floor).setScale(2);
        }
    }

    /** A user name's role, in lower case (clerk or steward). */
    public record RoleView(String user, String role) {
        static RoleView of(SheetRole role) {
            return new RoleView(role.getUserName(), role.getRole().name().toLowerCase());
        }
    }

    public record RoleForm(
            @NotBlank @Size(max = 100) String user,
            @NotNull @Pattern(regexp = "clerk|steward") String role) {

        Role roleValue() {
            return Role.valueOf(role.toUpperCase());
        }
    }

    private final SettingsService service;

    public SettingsController(SettingsService service) {
        this.service = service;
    }

    @GetMapping("/settings")
    public SettingsView settings(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_-]+") String sheetId,
            @RequestHeader(SessionController.USER_HEADER) @NotBlank String user) {
        return SettingsView.of(service.settings(sheetId, user));
    }

    /** Save the sheet's settings given; one left out keeps its value. */
    @PutMapping("/settings")
    public SettingsView save(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_-]+") String sheetId,
            @RequestHeader(SessionController.USER_HEADER) @NotBlank String user,
            @Valid @RequestBody SettingsForm form) {
        return SettingsView.of(service.save(sheetId, user, form.clerkLimit() != null, form.clerkLimitValue(),
                form.floorValue()));
    }

    /** The roles the sheet gives user names, by name. */
    @GetMapping("/roles")
    public List<RoleView> roles(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_-]+") String sheetId,
            @RequestHeader(SessionController.USER_HEADER) @NotBlank String user) {
        return service.roles(sheetId).stream().map(RoleView::of).toList();
    }

    /** Give a user name a role (clerk or steward); any other role is refused (400). */
    @PutMapping("/roles")
    public RoleView setRole(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_-]+") String sheetId,
            @RequestHeader(SessionController.USER_HEADER) @NotBlank String user,
            @Valid @RequestBody RoleForm form) {
        return RoleView.of(service.setRole(sheetId, user, form.user().trim(), form.roleValue()));
    }
}
package net.officefloor.hq.app.sheet;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.Instant;
import java.time.LocalDate;

/** A sheet: the unit everything else in the app is kept under. */
@Entity
@Table(name = "sheet")
public class Sheet {

    @Id
    private String id;

    @Column(name = "created_by", nullable = false)
    private String createdBy;

    @Column(name = "created_at", nullable = false)
    private Instant createdAt;

    /** The sheet's "today": every date-dependent decision in the sheet uses it, never the clock. */
    @Column(name = "today", nullable = false)
    private LocalDate today;

    /** The last claim number the sheet gave out; the next opened claim gets one more. */
    @Column(name = "last_claim_number", nullable = false)
    private int lastClaimNumber;

    /** A clerk may settle a claim only when its due is at or below this; none: no limit. */
    @Column(name = "clerk_limit", precision = 15, scale = 2)
    private BigDecimal clerkLimit;

    /** A claim's live due is at least this; a fixed, bound or closed-period figure is not changed by it. */
    @Column(name = "floor", nullable = false, precision = 15, scale = 2)
    private BigDecimal floor = new BigDecimal("1.00");

    protected Sheet() {}

    public Sheet(String id, String createdBy, Instant createdAt, LocalDate today) {
        this.id = id;
        this.createdBy = createdBy;
        this.createdAt = createdAt;
        this.today = today;
    }

    public String getId() { return id; }

    public String getCreatedBy() { return createdBy; }

    public Instant getCreatedAt() { return createdAt; }

    public LocalDate getToday() { return today; }

    public void setToday(LocalDate today) { this.today = today; }

    public BigDecimal getClerkLimit() { return clerkLimit; }

    public void setClerkLimit(BigDecimal clerkLimit) { this.clerkLimit = clerkLimit; }

    public BigDecimal getFloor() { return floor; }

    public void setFloor(BigDecimal floor) { this.floor = floor; }

    /** Give out the sheet's next claim number. */
    public int takeClaimNumber() { return ++lastClaimNumber; }
}
-- The sheet's floor: a claim's live due is at least this (two decimals). It starts at 1.00.
ALTER TABLE sheet ADD COLUMN floor DECIMAL(15, 2) DEFAULT 1.00 NOT NULL;
-- The sheet's clerk limit: a clerk may settle a claim only when its due is at or below it (two
-- decimals). None: no limit.
ALTER TABLE sheet ADD COLUMN clerk_limit DECIMAL(15, 2);
-- The role the sheet gives a user name. A name with none is a clerk.
CREATE TABLE sheet_role (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    user_name VARCHAR(100) NOT NULL,
    role      VARCHAR(20)  NOT NULL CHECK (role IN ('CLERK', 'STEWARD'))
);
CREATE UNIQUE INDEX sheet_role_sheet_user ON sheet_role (sheet_id, user_name);

